#!/bin/bash
# MacIsland Notch: self-contained source build, install, and restore.
# Generated by scripts/build_installer.py from modular sources in src/.
# Based on MakrSas/MacIsland a54047f69eceb4eaabd4f80034166fe23c8a0e7e.
set -euo pipefail
MODE="${1:-install}"
case "$MODE" in
  install|--check|--uninstall) ;;
  *) echo "Usage: bash install.sh [--check|--uninstall]" >&2; exit 2 ;;
esac
[[ $# -le 1 ]] || { echo "Too many arguments" >&2; exit 2; }
[[ "$(uname -s)" == Darwin ]] || { echo "macOS only" >&2; exit 1; }
[[ "$EUID" -ne 0 ]] || { echo "Run as your logged-in user, without sudo." >&2; exit 1; }
SCRATCH="$(mktemp -d "${TMPDIR:-/tmp}/macisland-notch-install.XXXXXX")"
cleanup() { rm -rf -- "$SCRATCH"; }
trap cleanup EXIT
trap 'exit 130' INT
trap 'exit 143' TERM

# defaults(1) with an absolute plist path can address a different preferences
# namespace from the entitled app group. Use the same explicit container as
# MenuBarAgent for both backup and restoration, leaving Apple's other keys alone.
# @EMBED src/installer/preferences.js preferences.js MACISLAND_PREFERENCES_JS

# Stage loader and installer scripts up front so --uninstall can cleanly detach
# providers using the current loader even without developer tools installed.
# @EMBED src/loader/loader.py loader.py MACISLAND_LOADER_PY

# @EMBED src/installer/manager.py manager.py MACISLAND_MANAGER

if [[ "$MODE" != --uninstall ]]; then
  [[ "$(uname -m)" == arm64 ]] || { echo "Apple Silicon only" >&2; exit 1; }
  [[ "$(sw_vers -buildVersion)" == 26C5035r ]] || {
    echo "Supported build: macOS 27.3 beta 26C5035r only." >&2; exit 1;
  }
  xcode-select -p >/dev/null 2>&1 || {
    echo "Install Apple developer tools first (Xcode or: xcode-select --install)." >&2; exit 1;
  }
  for tool in clang swiftc; do
    /usr/bin/xcrun --find "$tool" >/dev/null 2>&1 || {
      echo "The selected developer tools have no $tool; select Xcode with: sudo xcode-select -s /Applications/Xcode.app" >&2; exit 1;
    }
  done
  SDK_VERSION="$(/usr/bin/xcrun --sdk macosx --show-sdk-version 2>/dev/null || true)"
  /usr/bin/awk -v v="$SDK_VERSION" 'BEGIN { n = split(v, a, "."); exit !(n >= 1 && (a[1] + 0 > 27 || (a[1] + 0 == 27 && a[2] + 0 >= 2))) }' || {
    echo "The macOS 27.2 SDK or later is required (selected SDK: ${SDK_VERSION:-none})." >&2; exit 1;
  }
  if [[ "$MODE" == install ]]; then
    csrutil status | grep -q 'status: disabled' || {
      echo "SIP must already be disabled; no protection settings were changed." >&2; exit 1;
    }
    /usr/bin/xcrun --find lldb >/dev/null 2>&1 || {
      echo "The AMFI-compatible loader requires LLDB in the selected developer tools." >&2; exit 1;
    }
  fi

  /usr/bin/python3 -m py_compile "$SCRATCH/loader.py" "$SCRATCH/manager.py"

  # @EMBED src/island/notch-layout.h notch-layout.h MACISLAND_NOTCH_LAYOUT_H

  # @EMBED src/island/island.c island.c MACISLAND_ISLAND_C

  # @EMBED src/island/notch.m notch.m MACISLAND_NOTCH_M

  # @EMBED src/island/short-host.m short-host.m MACISLAND_SHORT_HOST_M

  # @EMBED src/island/safearea.m safearea.m MACISLAND_SAFEAREA_M

  # @EMBED src/island/mask.m mask.m MACISLAND_MASK_M

  # @EMBED src/providers/provider-abi.c provider-abi.c MACISLAND_PROVIDER_ABI_C

  # @EMBED src/providers/provider-body.S provider-body.S MACISLAND_PROVIDER_BODY_S

  # @EMBED src/providers/witness.swift witness.swift MACISLAND_WITNESS_SWIFT

  # @EMBED src/providers/music.swift music.swift MACISLAND_MUSIC_SWIFT

  # @EMBED src/providers/music-layout.swift music-layout.swift MACISLAND_MUSIC_LAYOUT_SWIFT

  # @EMBED src/providers/clock.swift clock.swift MACISLAND_CLOCK_SWIFT

  # @EMBED src/providers/spotlight.m spotlight.m MACISLAND_SPOTLIGHT_M

  echo "Building native notch patch from embedded source..."
  /usr/bin/xcrun clang -target arm64e-apple-macos27.2 -dynamiclib -fobjc-arc -Wall -Wextra -Werror \
    -I"$SCRATCH" \
    -o "$SCRATCH/island.dylib" "$SCRATCH/island.c" "$SCRATCH/notch.m" \
    "$SCRATCH/safearea.m" "$SCRATCH/short-host.m" "$SCRATCH/mask.m" \
    -framework AppKit -framework QuartzCore -F/System/Library/PrivateFrameworks \
    -framework CoreUtils -undefined dynamic_lookup
  /usr/bin/codesign -f -s - "$SCRATCH/island.dylib"
  /usr/bin/codesign --verify --strict "$SCRATCH/island.dylib"
  /usr/bin/xcrun clang -target arm64e-apple-macos27.2 -fobjc-arc -Wall -Wextra -Werror \
    -c "$SCRATCH/spotlight.m" -o "$SCRATCH/spotlight.o"
  /usr/bin/xcrun clang -target arm64e-apple-macos27.2 -Wall -Wextra -Werror \
    -c "$SCRATCH/provider-abi.c" -o "$SCRATCH/provider-abi.o"
  /usr/bin/xcrun clang -target arm64e-apple-macos27.2 \
    -c "$SCRATCH/provider-body.S" -o "$SCRATCH/provider-body.o"
  /usr/bin/xcrun swiftc -target arm64e-apple-macos27.2 -module-name MacIslandMusic \
    -module-cache-path "$SCRATCH/swift-modules" -O -emit-library \
    "$SCRATCH/witness.swift" "$SCRATCH/music.swift" "$SCRATCH/music-layout.swift" "$SCRATCH/clock.swift" \
    "$SCRATCH/provider-abi.o" "$SCRATCH/provider-body.o" "$SCRATCH/spotlight.o" \
    -Xlinker -undefined -Xlinker dynamic_lookup \
    -Xlinker -install_name -Xlinker @rpath/notch-music.dylib \
    -o "$SCRATCH/notch-music.dylib"
  /usr/bin/codesign -f -s - "$SCRATCH/notch-music.dylib"
  /usr/bin/codesign --verify --strict "$SCRATCH/notch-music.dylib"
  if [[ "$MODE" == --check ]]; then
    echo "Loader syntax, native build, and signature checks passed. No installation or preference changes."
    exit 0
  fi
fi

/usr/bin/python3 "$SCRATCH/manager.py" "$MODE" "$SCRATCH"
